import type { BankQuestion } from "@/lib/bank";

/** Differentiation and Its Applications (Mathematics (JEE)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"math-differentiation-applications-1","question":"d/dx (x² e^x) equals:","options":["e^x (x² + 2x)","2x e^x","x² e^x","e^x (2x + 1)"],"answer":0,"explanation":"Product rule: (x²)' e^x + x² (e^x)' = 2x e^x + x² e^x = e^x(x² + 2x).","difficulty":"easy"},
  {"id":"math-differentiation-applications-2","question":"The slope of the tangent to y = x³ − 3x at x = 2 is:","options":["3","6","12","9"],"answer":3,"explanation":"dy/dx = 3x² − 3; at x = 2 this is 12 − 3 = 9.","difficulty":"easy"},
  {"id":"math-differentiation-applications-3","question":"The minimum value of f(x) = x² − 4x + 7 is:","options":["7","2","3","4"],"answer":2,"explanation":"f'(x) = 2x − 4 = 0 gives x = 2, and f''(x) = 2 > 0 so it is a minimum. f(2) = 4 − 8 + 7 = 3. Option 2 is the location of the minimum, not its value.","difficulty":"easy"},
  {"id":"math-differentiation-applications-4","question":"If x² + y² = 25, then dy/dx at the point (3, 4) is:","options":["3/4","−3/4","−4/3","4/3"],"answer":1,"explanation":"Differentiate implicitly: 2x + 2y dy/dx = 0, so dy/dx = −x/y = −3/4 at (3, 4).","difficulty":"moderate"},
  {"id":"math-differentiation-applications-5","question":"d/dx ln(sec x + tan x) equals:","options":["tan x","sec x","sec² x","sec x tan x"],"answer":1,"explanation":"Derivative = (sec x tan x + sec² x)/(sec x + tan x) = sec x (tan x + sec x)/(sec x + tan x) = sec x. This is why ∫ sec x dx = ln|sec x + tan x| + C.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-6","question":"f(x) = x³ − 6x² + 9x + 1 is strictly decreasing on:","options":["(1, 3)","(−∞, 1)","(3, ∞)","(1, ∞)"],"answer":0,"explanation":"f'(x) = 3x² − 12x + 9 = 3(x − 1)(x − 3), which is negative exactly between the roots, i.e. on (1, 3).","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-7","question":"For f(x) = x² − 4x + 3 on [1, 3], the value of c given by Rolle's theorem is:","options":["2.5","1","3","2"],"answer":3,"explanation":"f(1) = f(3) = 0, so Rolle's theorem applies. f'(c) = 2c − 4 = 0 gives c = 2, which lies inside (1, 3).","difficulty":"moderate"},
  {"id":"math-differentiation-applications-8","question":"The equation of the normal to y = x² at the point (1, 1) is:","options":["x − 2y = −1","2x − y = 1","x + 2y = 3","2x + y = 3"],"answer":2,"explanation":"Tangent slope dy/dx = 2x = 2, so the normal slope is −1/2. Normal: y − 1 = −(1/2)(x − 1), i.e. x + 2y = 3. Option 2x − y = 1 is the tangent, not the normal.","difficulty":"moderate"},
  {"id":"math-differentiation-applications-9","question":"If y = sin⁻¹(2x/(1 + x²)) with |x| < 1, then dy/dx equals:","options":["2/√(1 − x²)","1/(1 + x²)","2/(1 + x²)","−2/(1 + x²)"],"answer":2,"explanation":"Put x = tan θ with |θ| < π/4: 2x/(1 + x²) = sin 2θ, so y = 2θ = 2 tan⁻¹x. Hence dy/dx = 2/(1 + x²). For |x| > 1 the sign flips, which is why the range matters.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-10","question":"For the cycloid x = a(t − sin t), y = a(1 − cos t), dy/dx at t = π/3 equals:","options":["1","√3","1/√3","2"],"answer":1,"explanation":"dy/dx = (dy/dt)/(dx/dt) = a sin t / (a(1 − cos t)) = 2 sin(t/2)cos(t/2)/(2 sin²(t/2)) = cot(t/2). At t = π/3 this is cot(π/6) = √3.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-11","question":"If x = t² and y = t³, then d²y/dx² equals:","options":["3/(4t)","3t/2","3/4","3t/4"],"answer":0,"explanation":"dy/dx = (3t²)/(2t) = 3t/2. Then d²y/dx² = d(3t/2)/dt ÷ dx/dt = (3/2)/(2t) = 3/(4t). Differentiating 3t/2 with respect to t only (giving 3/2) is the usual error.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-12","question":"The number of tangents to the curve y = x³ that pass through the point (0, 2) is:","options":["0","3","2","1"],"answer":3,"explanation":"Tangent at (a, a³): y = 3a²x − 2a³. Passing through (0, 2) requires −2a³ = 2, so a = −1 is the only real solution. Exactly one tangent.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-13","question":"The difference between the maximum and minimum values of f(x) = sin x + cos x on [0, π] is:","options":["√2","2","1","√2 + 1"],"answer":3,"explanation":"f(x) = √2 sin(x + π/4). On [0, π], x + π/4 runs from π/4 to 5π/4, so the maximum is √2 (at x = π/4) and the minimum is −1 (at x = π, the endpoint). Difference = √2 + 1. Taking −√2 as the minimum ignores the interval.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-14","question":"For f(x) = x³ on [0, 2], the value of c in Lagrange's mean value theorem is:","options":["1","4/3","2/√3","√3"],"answer":2,"explanation":"f'(c) = (f(2) − f(0))/(2 − 0) = 8/2 = 4, so 3c² = 4 and c = 2/√3 ≈ 1.15, which lies in (0, 2).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-15","question":"A 10 m ladder leans against a wall. Its foot slides away from the wall at 2 m/s. When the foot is 6 m from the wall, the top slides down at:","options":["2 m/s","1.5 m/s","3 m/s","0.75 m/s"],"answer":1,"explanation":"x² + y² = 100 gives 2x dx/dt + 2y dy/dt = 0. At x = 6, y = 8: dy/dt = −(6·2)/8 = −1.5 m/s, i.e. the top moves down at 1.5 m/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-16","question":"The acute angle between the curves y = x² and x = y² at the point (1, 1) is:","options":["tan⁻¹(3/4)","tan⁻¹(4/3)","π/4","π/2"],"answer":0,"explanation":"Slopes at (1, 1): for y = x², m₁ = 2x = 2; for x = y², 1 = 2y dy/dx so m₂ = 1/2. tan θ = |m₁ − m₂|/(1 + m₁m₂) = (3/2)/2 = 3/4, so θ = tan⁻¹(3/4).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-17","question":"The minimum value of f(x) = x^x for x > 0 is:","options":["e^(−1/e)","1/e","e^(1/e)","1"],"answer":0,"explanation":"ln f = x ln x, so f'/f = ln x + 1. f' = 0 at x = 1/e; f' < 0 before and > 0 after, so it is a minimum. Minimum value = (1/e)^(1/e) = e^(−1/e). Option 1/e is the location, not the value.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-18","question":"The sum of all real values of a for which y = e^(ax) satisfies y'' − 5y' + 6y = 0 is:","options":["6","1","−5","5"],"answer":3,"explanation":"Substituting y = e^(ax): e^(ax)(a² − 5a + 6) = 0, so a² − 5a + 6 = 0, giving a = 2 or 3. Sum = 5 (the product would be 6).","difficulty":"hard"},
  {"id":"math-differentiation-applications-19","question":"How many of the following statements are correct?\n(1) If f'(c) = 0, then f has a local extremum at c.\n(2) If f'(x) > 0 on (a, b), then f is strictly increasing on (a, b).\n(3) A function continuous on a closed interval [a, b] attains both its maximum and minimum there.\n(4) If f is differentiable at c and has a local maximum at c, then f'(c) = 0.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(2), (3) and (4) are true. (1) is false: f(x) = x³ has f'(0) = 0 but no extremum at 0 (a point of inflection). Three correct.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-20","question":"Squares of side x are cut from the corners of a 12 cm × 12 cm sheet and the sides are folded up to form an open box. The maximum volume (in cm³) is:","options":["144","96","128","108"],"answer":2,"explanation":"V = x(12 − 2x)². V' = (12 − 2x)² − 4x(12 − 2x) = (12 − 2x)(12 − 6x) = 0 gives x = 2 (x = 6 gives zero volume). V(2) = 2 × 8² = 128 cm³.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-21","question":"For f(x) = 2x³ − 9x² + 12x + 5 on [0, 3], the absolute maximum minus the absolute minimum equals:","options":["5","9","14","10"],"answer":1,"explanation":"f'(x) = 6x² − 18x + 12 = 6(x − 1)(x − 2). Check critical points and endpoints: f(0) = 5, f(1) = 10, f(2) = 9, f(3) = 14. Absolute max 14 (endpoint), absolute min 5 (endpoint). Difference = 9. Using only the local extrema (10 − 9 = 1) misses the endpoints.","difficulty":"very-hard","source":"JEE Main 2021 pattern"},
  {"id":"math-differentiation-applications-22","question":"Assertion (A): f(x) = x³ + x has no local maximum or minimum.\nReason (R): f'(x) = 3x² + 1 > 0 for all real x, so f is strictly increasing everywhere.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"f'(x) = 3x² + 1 is never zero and always positive, so f is strictly increasing on R and cannot have a local extremum. R is true and directly explains A.","difficulty":"very-hard"},
  {"id":"math-differentiation-applications-23","question":"The line y = mx + c touches the parabola y = x² at a point in the first quadrant and passes through (0, −4). Then m equals:","options":["2","4","8","−4"],"answer":1,"explanation":"Tangent at (a, a²): y = 2ax − a². Through (0, −4): −a² = −4, so a = 2 (first quadrant). Then m = 2a = 4.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-24","question":"If y = tan⁻¹((√(1 + x²) − 1)/x), x > 0, then dy/dx at x = 1 equals:","options":["1/4","1/(2√2)","1/2","1"],"answer":0,"explanation":"Put x = tan θ: (sec θ − 1)/tan θ = (1 − cos θ)/sin θ = tan(θ/2), so y = θ/2 = (1/2)tan⁻¹x. dy/dx = 1/(2(1 + x²)) = 1/4 at x = 1.","difficulty":"very-hard","source":"JEE Main 2020 pattern"},
  {"id":"math-differentiation-applications-25","question":"f(x) = x³ + ax² + bx + c has a local maximum at x = −1 and a local minimum at x = 3. Then a + b equals:","options":["6","−6","12","−12"],"answer":3,"explanation":"f'(x) = 3x² + 2ax + b must equal 3(x + 1)(x − 3) = 3x² − 6x − 9. Comparing: 2a = −6 so a = −3, and b = −9. a + b = −12. (Sign check: f' goes + to − at −1, so maximum; − to + at 3, so minimum.)","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-26","question":"For k in the open interval (−2, 2), the number of distinct real roots of x³ − 3x + k = 0 is:","options":["1","2","3","depends on the sign of k"],"answer":2,"explanation":"g(x) = x³ − 3x + k has g' = 3(x² − 1), local max g(−1) = 2 + k > 0 and local min g(1) = −2 + k < 0 for k in (−2, 2). The cubic crosses zero once before −1, once between −1 and 1, once after 1: three distinct real roots.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-differentiation-applications-27","question":"f is differentiable on R with |f'(x)| ≤ 2 for all x and f(0) = 1. Which of the following MUST be true?","options":["f(3) ≥ 7","f(3) = 7","f(3) ≤ 7","f(3) ≤ 6"],"answer":2,"explanation":"By LMVT, f(3) − f(0) = 3f'(c) for some c, so |f(3) − 1| ≤ 6, i.e. −5 ≤ f(3) ≤ 7. Hence f(3) ≤ 7 must hold. f(3) ≤ 6 need not hold (f(x) = 2x + 1 gives f(3) = 7).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-28","question":"The tangent to y = x³ − x at the point (1, 0) meets the curve again at:","options":["(−1, 0)","(−2, −6)","(2, 6)","(−2, 6)"],"answer":1,"explanation":"Slope at x = 1: 3x² − 1 = 2, tangent y = 2(x − 1). Intersect with the curve: x³ − x = 2x − 2, i.e. x³ − 3x + 2 = (x − 1)²(x + 2) = 0. The new point has x = −2, y = −8 + 2 = −6.","difficulty":"very-hard","source":"JEE Main 2023 pattern"},
  {"id":"math-differentiation-applications-29","question":"The shortest distance from the point (0, 2) to the parabola y = x² is:","options":["√7/2","√3/2","2","√15/4"],"answer":0,"explanation":"D² = x² + (x² − 2)². d(D²)/dx = 2x + 4x(x² − 2) = 2x(2x² − 3) = 0 gives x = 0 or x² = 3/2. At x² = 3/2: D² = 3/2 + 1/4 = 7/4, so D = √7/2 ≈ 1.32, smaller than the value 2 at x = 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-30","question":"If f(x) = e^x sin x, then f''(x) − 2f'(x) + 2f(x) equals:","options":["2f(x)","e^x sin x","2e^x cos x","0"],"answer":3,"explanation":"f' = e^x(sin x + cos x), f'' = e^x(sin x + cos x) + e^x(cos x − sin x) = 2e^x cos x. Then f'' − 2f' + 2f = 2e^x cos x − 2e^x sin x − 2e^x cos x + 2e^x sin x = 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-differentiation-applications-31", "question": "If y = ln(sin x), then dy/dx equals:", "options": ["cot x", "tan x", "1/sin x", "−cot x"], "answer": 0, "explanation": "By the chain rule: (1/sin x) × cos x = cot x.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-32", "question": "The radius of a circle increases at 2 cm/s. When the radius is 5 cm, its area increases at:", "options": ["10π cm²/s", "25π cm²/s", "4π cm²/s", "20π cm²/s"], "answer": 3, "explanation": "dA/dt = 2πr·dr/dt = 2π × 5 × 2 = 20π cm²/s.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-33", "question": "f(x) = x e⁻ˣ is increasing on:", "options": ["(1, ∞)", "(0, ∞)", "(−∞, 1)", "(−∞, 0)"], "answer": 2, "explanation": "f′(x) = e⁻ˣ(1 − x), which is positive exactly when x < 1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-34", "question": "If y = x^(sin x), x > 0, then dy/dx equals:", "options": ["x^(sin x)[cos x ln x + (sin x)/x]", "sin x · x^(sin x − 1)", "x^(sin x) cos x ln x", "x^(sin x)[sin x ln x + (cos x)/x]"], "answer": 0, "explanation": "ln y = sin x ln x, so y′/y = cos x ln x + sin x/x. The power rule alone (second option) ignores that the exponent varies.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-35", "question": "Using differentials, the approximate value of √25.1 is:", "options": ["5.1", "5.001", "5.02", "5.01"], "answer": 3, "explanation": "With f(x) = √x, f(25 + 0.1) ≈ 5 + 0.1/(2 × 5) = 5 + 0.01 = 5.01.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-36", "question": "If y = sin(m sin⁻¹x), then (1 − x²)y″ − xy′ equals:", "options": ["m²y", "−m²y", "−my", "0"], "answer": 1, "explanation": "y′ = m cos(m sin⁻¹x)/√(1 − x²), so (1 − x²)y′² = m²(1 − y²). Differentiating and dividing by 2y′: (1 − x²)y″ − xy′ = −m²y.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-37", "question": "The tangent to x^(2/3) + y^(2/3) = 2 at (1, 1) is:", "options": ["x − y = 0", "x + y = 2", "x + y = 1", "2x + y = 3"], "answer": 1, "explanation": "Implicitly, (2/3)x^(−1/3) + (2/3)y^(−1/3)y′ = 0, so y′ = −(y/x)^(1/3) = −1 at (1, 1). The tangent is y − 1 = −(x − 1), i.e. x + y = 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-38", "question": "The maximum value of f(x) = (ln x)/x for x > 0 is:", "options": ["e", "1", "0", "1/e"], "answer": 3, "explanation": "f′(x) = (1 − ln x)/x² is zero at x = e, positive before it and negative after, so the maximum is f(e) = 1/e.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-39", "question": "The height of the right circular cylinder of maximum volume inscribed in a sphere of radius R is:", "options": ["2R/√3", "R√2", "R", "4R/3"], "answer": 0, "explanation": "With height h, the cylinder's radius satisfies r² = R² − h²/4, so V = π(R²h − h³/4). V′ = π(R² − 3h²/4) = 0 gives h = 2R/√3, a maximum since V″ < 0.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-differentiation-applications-40", "question": "The local minimum value of f(x) = x^(2/3)(x − 5) is:", "options": ["0", "−3∛2", "−3∛4", "−6"], "answer": 2, "explanation": "f′(x) = (5/3)x^(2/3) − (10/3)x^(−1/3) = (5/3)x^(−1/3)(x − 2). The critical points are x = 0 (f′ undefined, local max with f = 0) and x = 2 (f′ goes from − to +). f(2) = 2^(2/3)(−3) = −3∛4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-41", "question": "Consider the following statements:\n(1) Rolle's theorem applies to f(x) = |x| on [−1, 1].\n(2) Lagrange's mean value theorem applies to f(x) = x^(1/3) on [−1, 1].\n(3) f(x) = x³ − 3x is decreasing on (−1, 1).\n(4) If f′(c) = 0 and f″(c) > 0, then f has a local minimum at c.\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(1) False: |x| is not differentiable at 0. (2) False: x^(1/3) has a vertical tangent at 0, so it is not differentiable there. (3) True: f′ = 3(x² − 1) < 0 on (−1, 1). (4) True: the second-derivative test. Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-42", "question": "The tangent to y = eˣ at some point passes through the origin. The normal to the curve at that point is:", "options": ["x + ey = 1 + e", "x + ey = 1 + e²", "ex + y = 2e", "x − ey = 1 − e²"], "answer": 1, "explanation": "The tangent at (a, eᵃ) is y − eᵃ = eᵃ(x − a). It passes through O when −eᵃ = −aeᵃ, i.e. a = 1, so the point is (1, e). The normal has slope −1/e: y − e = −(x − 1)/e, i.e. x + ey = 1 + e².", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-43", "question": "The maximum area of a rectangle with sides parallel to the axes inscribed in the ellipse x²/16 + y²/9 = 1 is:", "options": ["12", "48", "24", "6"], "answer": 2, "explanation": "Take the vertex (4 cos θ, 3 sin θ). The area is 4 × 4 cos θ × 3 sin θ = 24 sin 2θ, with maximum 24 (in general 2ab).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-44", "question": "For f(x) = x³ + bx² + cx + d with 0 < b² < c, f is:", "options": ["strictly increasing on R", "strictly decreasing on R", "increasing then decreasing", "decreasing then increasing"], "answer": 0, "explanation": "f′(x) = 3x² + 2bx + c has discriminant 4b² − 12c = 4(b² − 3c) < 0, since b² < c < 3c. So f′ > 0 everywhere and f is strictly increasing.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-differentiation-applications-45", "question": "Water is poured at 4 cm³/s into an inverted cone whose base radius is 5 cm and height 10 cm. When the water is 4 cm deep, its level rises at:", "options": ["4/π cm/s", "1/π cm/s", "1/(4π) cm/s", "2/π cm/s"], "answer": 1, "explanation": "By similar triangles r = h/2, so V = (1/3)π(h/2)²h = πh³/12 and dV/dt = (πh²/4)·dh/dt. At h = 4: 4 = 4π·dh/dt, so dh/dt = 1/π cm/s.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-46", "question": "d/dx (sin²x) equals:", "options": ["2 sin x", "cos²x", "sin 2x", "2 cos x"], "answer": 2, "explanation": "By the chain rule, d/dx (sin x)² = 2 sin x · cos x = sin 2x.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-47", "question": "If y = e^(3x), then d²y/dx² equals:", "options": ["9e^(3x)", "3e^(3x)", "e^(3x)", "6e^(3x)"], "answer": 0, "explanation": "y′ = 3e^(3x) and y″ = 9e^(3x).", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-48", "question": "d/dx [ln(x + √(x² + 1))] equals:", "options": ["1/(x + √(x² + 1))", "x/√(x² + 1)", "√(x² + 1)", "1/√(x² + 1)"], "answer": 3, "explanation": "The derivative is [1 + x/√(x² + 1)]/(x + √(x² + 1)) = [(√(x² + 1) + x)/√(x² + 1)]/(x + √(x² + 1)) = 1/√(x² + 1).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-49", "question": "For the curve x³ + y³ = 3xy, the value of dy/dx at the point (3/2, 3/2) is:", "options": ["1", "−1", "0", "−1/2"], "answer": 1, "explanation": "Differentiating: 3x² + 3y²y′ = 3y + 3xy′, so y′ = (y − x²)/(y² − x). At (3/2, 3/2): (3/2 − 9/4)/(9/4 − 3/2) = (−3/4)/(3/4) = −1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-50", "question": "The volume of a cube increases at 9 cm³/s. When its edge is 10 cm, its surface area increases at:", "options": ["1.8 cm²/s", "3.6 cm²/s", "0.03 cm²/s", "36 cm²/s"], "answer": 1, "explanation": "V = a³ gives 9 = 3a²·da/dt = 300·da/dt, so da/dt = 0.03 cm/s. S = 6a² gives dS/dt = 12a·da/dt = 120 × 0.03 = 3.6 cm²/s.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-51", "question": "f(x) = 2x³ − 15x² + 36x + 1 has a local maximum at:", "options": ["x = 3", "x = −2", "x = 6", "x = 2"], "answer": 3, "explanation": "f′(x) = 6x² − 30x + 36 = 6(x − 2)(x − 3). f″(x) = 12x − 30 is negative at x = 2 (maximum) and positive at x = 3 (minimum).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-52", "question": "The tangent to y = x³ − 3x² − 9x + 7 is parallel to the x-axis at:", "options": ["x = −1 and x = 3", "x = 1 and x = −3", "x = 3 only", "x = 0 and x = 2"], "answer": 0, "explanation": "y′ = 3x² − 6x − 9 = 3(x − 3)(x + 1) = 0 gives x = 3 and x = −1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-53", "question": "If y = 1/(1 + x), then the fifth derivative y⁽⁵⁾ at x = 0 equals:", "options": ["120", "−24", "−120", "24"], "answer": 2, "explanation": "The nth derivative of (1 + x)⁻¹ is (−1)ⁿ n!/(1 + x)ⁿ⁺¹. For n = 5 at x = 0 this is −5! = −120.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-54", "question": "The derivative of ln x with respect to 1/x, at x = 2, is:", "options": ["2", "−1/2", "1/2", "−2"], "answer": 3, "explanation": "d(ln x)/d(1/x) = (1/x)/(−1/x²) = −x, which is −2 at x = 2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-55", "question": "For the curve x = 2 cos θ − cos 2θ, y = 2 sin θ − sin 2θ, the value of dy/dx at θ = π/2 is:", "options": ["1", "−1", "0", "√3"], "answer": 1, "explanation": "dy/dθ = 2 cos θ − 2 cos 2θ = 0 + 2 = 2 and dx/dθ = −2 sin θ + 2 sin 2θ = −2 + 0 = −2 at θ = π/2, so dy/dx = −1. (In general dy/dx = tan(3θ/2), and tan(3π/4) = −1.)", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-56", "question": "f(x) = x³ + ax² + 3x + 5 is increasing on the whole real line exactly when:", "options": ["−3 < a < 3", "a ≥ 3", "−3 ≤ a ≤ 3", "−√3 ≤ a ≤ √3"], "answer": 2, "explanation": "Need f′(x) = 3x² + 2ax + 3 ≥ 0 for all x, i.e. discriminant 4a² − 36 ≤ 0, so −3 ≤ a ≤ 3. At a = ±3, f′ = 3(x ± 1)² vanishes only at one point, so f is still increasing.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-57", "question": "The value of c given by Lagrange's mean value theorem for f(x) = ln x on [1, e] is:", "options": ["e − 1", "(e + 1)/2", "√e", "1/(e − 1)"], "answer": 0, "explanation": "f′(c) = [f(e) − f(1)]/(e − 1) = 1/(e − 1). Since f′(c) = 1/c, c = e − 1 ≈ 1.72, which lies in (1, e).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-58", "question": "A closed cylindrical can of fixed volume has the least total surface area when its height h and radius r satisfy:", "options": ["h = 2r", "h = r", "h = 3r", "h = r/2"], "answer": 0, "explanation": "With V = πr²h fixed, S = 2πr² + 2V/r. dS/dr = 4πr − 2V/r² = 0 gives V = 2πr³, so πr²h = 2πr³ and h = 2r (height equals diameter).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-59", "question": "The point on the parabola y = x² nearest to the line y = 2x − 4 is:", "options": ["(2, 4)", "(−1, 1)", "(1, 1)", "(1/2, 1/4)"], "answer": 2, "explanation": "At the nearest point the tangent is parallel to the line: y′ = 2x = 2, so x = 1 and the point is (1, 1). (The line does not meet the parabola, since x² − 2x + 4 > 0.)", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-60", "question": "The number of real roots of eˣ = x² is:", "options": ["0", "1", "2", "3"], "answer": 1, "explanation": "For x < 0, eˣ − x² goes from −∞ to 1 and is increasing, so there is exactly one negative root. For x > 0, eˣ/x² has minimum e²/4 ≈ 1.85 > 1 at x = 2, so eˣ > x² there. Total: one real root.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-61", "question": "The acute angle between the curves x² + 4y² = 8 and x² − 2y² = 2 at their point of intersection in the first quadrant is:", "options": ["90°", "tan⁻¹ (1/3)", "45°", "tan⁻¹ 3"], "answer": 3, "explanation": "Subtracting gives 6y² = 6, so the point is (2, 1). Slopes: for the first curve y′ = −x/(4y) = −1/2; for the second y′ = x/(2y) = 1. tan θ = |(1 − (−1/2))/(1 + (1)(−1/2))| = (3/2)/(1/2) = 3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-62", "question": "For f(x) = x + 1/x (x ≠ 0), which statement is correct?", "options": ["Its local maximum value is 2 and local minimum value is −2", "It has a local minimum at x = −1", "Its local maximum value −2 is less than its local minimum value 2", "It has no local extrema"], "answer": 2, "explanation": "f′(x) = 1 − 1/x² = 0 at x = ±1; f″(x) = 2/x³ is negative at −1 (local max, value −2) and positive at 1 (local min, value 2). A local maximum can be smaller than a local minimum because they sit on different branches.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-63", "question": "The sum of the x- and y-intercepts of any tangent to the curve √x + √y = 2 is:", "options": ["2", "8", "it depends on the point of contact", "4"], "answer": 3, "explanation": "At (p², q²) with p + q = 2, y′ = −√y/√x = −q/p and the tangent is x/p + y/q = p + q. Its intercepts are p(p + q) and q(p + q), whose sum is (p + q)² = 4. In general it is a for √x + √y = √a.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-64", "question": "On the interval [0, π/2], f(x) = sin⁴x + cos⁴x is increasing on:", "options": ["[π/4, π/2]", "[0, π/4]", "[0, π/2]", "[π/8, 3π/8]"], "answer": 0, "explanation": "f(x) = 1 − 2sin²x cos²x = 1 − (1/2)sin²2x = 3/4 + (1/4)cos 4x, so f′(x) = −sin 4x. On (π/4, π/2), 4x is in (π, 2π) where sin 4x < 0, so f′ > 0. On (0, π/4), f decreases.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-65", "question": "The number of critical points of f(x) = |x − 1| + (x − 2)² is:", "options": ["1", "2", "3", "0"], "answer": 1, "explanation": "For x > 1, f′ = 1 + 2(x − 2) = 0 at x = 3/2 (valid). For x < 1, f′ = −1 + 2(x − 2) = 0 at x = 5/2 (not in x < 1, rejected). At x = 1, f is not differentiable, so it is a critical point too. Critical points: 1 and 3/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-66", "question": "A man 2 m tall walks directly away from a 6 m high lamp post at 5 km/h. The tip of his shadow moves at:", "options": ["2.5 km/h", "5 km/h", "10 km/h", "7.5 km/h"], "answer": 3, "explanation": "If he is x from the post and his shadow is s long, similar triangles give s/2 = (x + s)/6, so s = x/2. The tip is at x + s = 3x/2 from the post, so it moves at (3/2)(5) = 7.5 km/h. 2.5 km/h is the rate at which the shadow lengthens.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-67", "question": "For f(x) = x⁴ − 4x³, how many of the following are correct?\n(1) f has a local minimum at x = 3.\n(2) f has a local maximum at x = 0.\n(3) The graph has points of inflection at x = 0 and x = 2.\n(4) f is decreasing on (−∞, 3].", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "f′(x) = 4x²(x − 3): negative for x < 3 (except 0) and positive for x > 3, so (1) and (4) are true and (2) is false (no sign change at 0). f″(x) = 12x(x − 2) changes sign at 0 and 2, so (3) is true. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-68", "question": "A right circular cone has a given slant height. Its volume is greatest when the semi-vertical angle θ satisfies:", "options": ["tan θ = 1/√2", "tan θ = √2", "θ = 45°", "tan θ = √3"], "answer": 1, "explanation": "With slant height l, r = l sin θ and h = l cos θ, so V = (π/3)l³ sin²θ cos θ. dV/dθ ∝ 2 sin θ cos²θ − sin³θ = 0 gives tan²θ = 2, i.e. tan θ = √2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-69", "question": "If x^y = e^(x − y), then dy/dx equals:", "options": ["1/(1 + ln x)", "ln x/(1 + ln x)", "ln x/(1 + ln x)²", "(1 + ln x)/ln x"], "answer": 2, "explanation": "Taking logs: y ln x = x − y, so y = x/(1 + ln x). Then dy/dx = [(1 + ln x) − x·(1/x)]/(1 + ln x)² = ln x/(1 + ln x)².", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-70", "question": "The maximum value of f(x) = x·e^(−x²) over all real x is:", "options": ["1/e", "1/√(2e)", "1/√e", "√2/e"], "answer": 1, "explanation": "f′(x) = e^(−x²)(1 − 2x²) = 0 at x = ±1/√2. The maximum is at x = 1/√2: f = (1/√2)e^(−1/2) = 1/√(2e).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-differentiation-applications-71","question":"The tangent to the curve x = t² + 3t − 8, y = 2t² − 2t − 5 at the point (2, −1) is:","options":["6x − 7y = 19","6x + 7y = 5","7x − 6y = 20","6x − 7y = 5"],"answer":0,"explanation":"x = 2 gives t = 2 or −5 and y = −1 gives t = 2 or −1, so the point is t = 2. dy/dx = (4t − 2)/(2t + 3) = 6/7. Tangent: y + 1 = (6/7)(x − 2), i.e. 6x − 7y = 19. Using dx/dy instead gives the line 7x − 6y = 20.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-72","question":"f(x) = x³ + 3x and g is the inverse of f. Then g′(4) equals:","options":["1/51","1/6","1/4","6"],"answer":1,"explanation":"g′(4) = 1/f′(g(4)). f(1) = 4, so g(4) = 1 and f′(1) = 3 + 3 = 6, giving 1/6. Writing 1/f′(4) = 1/51 evaluates f′ at the wrong point.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-73","question":"f(x) = x ln x (x > 0) is strictly decreasing on:","options":["(1/e, ∞)","(0, e)","(0, 1/e)","(0, 1)"],"answer":2,"explanation":"f′(x) = ln x + 1 < 0 ⇔ ln x < −1 ⇔ x < 1/e. So f decreases on (0, 1/e) and increases after it. (0, 1) is where f is negative, not where it decreases.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-74","question":"For 1/√2 < x < 1, the derivative of sin⁻¹(2x√(1 − x²)) with respect to x is:","options":["2/√(1 − x²)","−1/√(1 − x²)","1/√(1 − x²)","−2/√(1 − x²)"],"answer":3,"explanation":"Put x = sin θ with θ in (π/4, π/2). Then 2x√(1 − x²) = sin 2θ with 2θ in (π/2, π), where sin⁻¹(sin 2θ) = π − 2θ. So the function is π − 2 sin⁻¹x and its derivative is −2/√(1 − x²). The answer +2/√(1 − x²) uses the principal-branch formula outside its range.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-75","question":"If y = x²eˣ, then the tenth derivative y⁽¹⁰⁾ at x = 0 equals:","options":["90","45","100","110"],"answer":0,"explanation":"By Leibniz, y⁽¹⁰⁾ = Σ ¹⁰Cₖ (x²)⁽ᵏ⁾ eˣ. At x = 0 only k = 2 survives ((x²)″ = 2): ¹⁰C₂ · 2 · e⁰ = 45 · 2 = 90. Forgetting the factor 2 gives 45.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-77","question":"The acute angle between the curves y = sin x and y = cos x at their point of intersection in (0, π/2) is:","options":["tan⁻¹(√2)","π/2","tan⁻¹(2√2)","π/4"],"answer":2,"explanation":"They meet at x = π/4, where the slopes are cos(π/4) = 1/√2 and −sin(π/4) = −1/√2. tan θ = |(m₁ − m₂)/(1 + m₁m₂)| = √2/(1 − 1/2) = 2√2. Forgetting the 1 + m₁m₂ denominator gives tan⁻¹(√2).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-78","question":"If x and y are positive with x + y = 10, the maximum value of x²y³ is:","options":["3125","3375","2916","3456"],"answer":3,"explanation":"Maximise f(x) = x²(10 − x)³: f′ = x(10 − x)²[2(10 − x) − 3x] = 0 ⇒ x = 4, y = 6 (split 10 in the ratio 2 : 3). Max = 16 · 216 = 3456. Taking x = y = 5 gives 3125, which is not the maximum.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-79","question":"A particle moves along the curve y = x² in the first quadrant so that its distance from the origin increases at 3√5 units/s. When x = 2, dx/dt equals:","options":["5/3","√5","15/2","3/5"],"answer":0,"explanation":"r² = x² + y² = x² + x⁴, so 2r·dr/dt = (2x + 4x³)·dx/dt. At x = 2: r = √20 = 2√5 and 2·2√5·3√5 = 60 = 36·dx/dt, giving dx/dt = 5/3 units/s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-differentiation-applications-80", "question": "f(x) = a sin x + (1/3) sin 3x has an extremum at x = π/3. Then:", "options": ["a = 2 and the extremum is a minimum", "a = 2 and the extremum is a maximum", "a = 1 and the extremum is a maximum", "a = −2 and the extremum is a minimum"], "answer": 1, "explanation": "f′(π/3) = a cos(π/3) + cos π = a/2 − 1 = 0 ⇒ a = 2. f″(x) = −2 sin x − 3 sin 3x, so f″(π/3) = −√3 + 0 < 0: a local maximum (value 2·(√3/2) + 0 = √3).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-81", "question": "How many of the following inequalities are true for every x in the stated range?\n(1) tan x > x for 0 < x < π/2.\n(2) sin x > x − x³/6 for x > 0.\n(3) ln(1 + x) > x − x²/2 for x > 0.\n(4) x/(1 + x) > ln(1 + x) for x > 0.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "Each follows from a function vanishing at 0 with a sign-definite derivative. (1) (tan x − x)′ = tan²x > 0. (2) g = sin x − x + x³/6: g‴ = 1 − cos x ≥ 0 makes g″, g′, g > 0. (3) (ln(1 + x) − x + x²/2)′ = x²/(1 + x) > 0. (4) is reversed: (ln(1 + x) − x/(1 + x))′ = x/(1 + x)² > 0, so ln(1 + x) > x/(1 + x). Three are true.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-differentiation-applications-82","question":"The minimum value of f(x) = 8/sin x + 27/cos x on (0, π/2) is:","options":["5√13","35","13√13","13"],"answer":2,"explanation":"f′ = −8 cos x/sin²x + 27 sin x/cos²x = 0 ⇒ tan³x = 8/27 ⇒ tan x = 2/3, so sin x = 2/√13, cos x = 3/√13. f = 8√13/2 + 27√13/3 = 4√13 + 9√13 = 13√13 ≈ 46.9. 35 = 8 + 27 is the value one gets by wrongly pretending sin x = cos x = 1.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-83","question":"The equation kx = ln x has exactly one real root precisely when:","options":["0 < k < 1/e","k = 1/e only","k < 1/e","k ≤ 0 or k = 1/e"],"answer":3,"explanation":"Roots correspond to h(x) = (ln x)/x = k. h increases on (0, e) from −∞ to 1/e and then decreases towards 0⁺. So a horizontal line y = k cuts it once when k = 1/e (tangency) or k ≤ 0 (only the rising branch; k = 0 gives x = 1), twice when 0 < k < 1/e, never when k > 1/e.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-differentiation-applications-84","question":"The shortest distance between the curves y = eˣ and y = ln x is:","options":["√2","1","1/√2","2√2"],"answer":0,"explanation":"The curves are mirror images in y = x, so the shortest distance is twice the least distance of y = eˣ from the line y = x. That occurs where the slope eˣ = 1, i.e. at (0, 1), at distance |0 − 1|/√2 = 1/√2. Hence the answer is 2 × 1/√2 = √2; 1/√2 is only half the gap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-differentiation-applications-85", "question": "The right circular cone of greatest volume is inscribed in a sphere. The ratio of its volume to the volume of the sphere is:", "options": ["1/3", "8/27", "4/9", "16/27"], "answer": 1, "explanation": "With sphere radius R and cone height h, the base radius satisfies r² = h(2R − h), so V = (π/3)(2Rh² − h³). dV/dh = 0 gives h = 4R/3, r² = 8R²/9 and V = (π/3)(8R²/9)(4R/3) = 32πR³/81. Dividing by 4πR³/3: (32/81)(3/4) = 8/27.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-differentiation-applications-86", "question": "For f(x) = (x − 1)²(x − 2)³, how many of the following are correct?\n(1) f has a local maximum at x = 1.\n(2) f has a local minimum at x = 7/5.\n(3) f has a local minimum at x = 2.\n(4) f has exactly two points of local extremum.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "f′(x) = (x − 1)(x − 2)²(5x − 7). Signs: + on (−∞, 1), − on (1, 7/5), + on (7/5, 2), + on (2, ∞). So x = 1 is a local max, 7/5 a local min, and x = 2 is not an extremum (f′ does not change sign there — a stationary inflection). (1), (2), (4) are true; three.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-differentiation-applications-87","question":"A tangent to the ellipse x²/9 + y²/4 = 1 at a point in the first quadrant meets the coordinate axes at A and B. The least possible length of AB is:","options":["6","√13","5","13/2"],"answer":2,"explanation":"Tangent at (3 cos θ, 2 sin θ): (x cos θ)/3 + (y sin θ)/2 = 1, so A = (3 sec θ, 0), B = (0, 2 cosec θ). AB² = 9 sec²θ + 4 cosec²θ = 13 + 9 tan²θ + 4 cot²θ ≥ 13 + 2·√36 = 25 (AM–GM, at tan²θ = 2/3). So AB_min = a + b = 5. √13 forgets the tan/cot terms.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-88","question":"f(x) = x³ + x and g is its inverse function. Then g″(2) equals:","options":["−1/16","3/32","−3/8","−3/32"],"answer":3,"explanation":"From f(g(x)) = x: g′ = 1/f′(g) and g″ = −f″(g)·g′/f′(g)² = −f″(g)/f′(g)³. Here g(2) = 1, f′(1) = 4, f″(1) = 6, so g″(2) = −6/64 = −3/32. Using f′(g)² instead of the cube gives −3/8.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-differentiation-applications-89","question":"The maximum value of f(x) = sin x(1 + cos x) on [0, π] is:","options":["3√3/4","1","3/2","√3/2"],"answer":0,"explanation":"f′ = cos x + cos²x − sin²x = cos x + cos 2x = 2cos²x + cos x − 1 = (2 cos x − 1)(cos x + 1). In (0, π) it vanishes at cos x = 1/2, x = π/3, where f = (√3/2)(3/2) = 3√3/4 ≈ 1.30 (the endpoints give 0). 1 is the value at x = π/2, not the maximum.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-90","question":"The number of points of local extremum of f(x) = x²·e^(−|x|) on R is:","options":["2","3","1","4"],"answer":1,"explanation":"For x > 0, f′ = (2x − x²)e^(−x) changes from + to − at x = 2 (local max); by symmetry x = −2 is a local max. At x = 0, f = 0 ≤ f(x) everywhere, so it is a local min (f′(0) = 0 too). Total 3. Counting only the solutions of f′ = 0 for x > 0 and forgetting x = 0 or −2 gives the wrong counts.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "math-differentiation-applications-91", "question": "f(x) = x² + 1 for x ≤ 1 and f(x) = k − x for x > 1. f has a local maximum at x = 1 exactly when:", "options": ["k = 3 only", "k < 3", "k ≤ 3", "k ≥ 3"], "answer": 2, "explanation": "f(1) = 2 and the left piece x² + 1 < 2 just left of 1. For x slightly more than 1, k − x < k − 1, so f(x) ≤ 2 there iff k − 1 ≤ 2, i.e. k ≤ 3. Continuity (k = 3) is NOT needed: for k < 3 the jump is downward and 1 is still a local maximum.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-differentiation-applications-92", "question": "The common tangents to the parabolas y = x² and y = −x² + 4x − 4 are:", "options": ["y = 0 only", "y = 4x − 4 only", "y = 2x − 1 and y = 4x − 4", "y = 0 and y = 4x − 4"], "answer": 3, "explanation": "y = mx + c touches y = x² iff m² + 4c = 0, and touches y = −x² + 4x − 4 iff (4 − m)² = 4(4 + c). Substituting c = −m²/4: 16 − 8m + m² = 16 − m² ⇒ m = 0 or 4, giving y = 0 (it touches both at their vertices (0, 0) and (2, 0)) and y = 4x − 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-differentiation-applications-93","question":"For f(x) = x²|x|, which statement is correct at x = 0?","options":["f is not differentiable","f is differentiable but not twice differentiable","f is thrice differentiable","f is twice differentiable but not thrice differentiable"],"answer":3,"explanation":"f = x³ for x ≥ 0 and −x³ for x < 0, so f′(x) = 3x|x| (f′(0) = 0) and f″(x) = 6|x| (f″(0) = lim 3h|h|/h = 0). But f‴ would be the derivative of 6|x| at 0, whose one-sided values are ±6. So f is exactly twice differentiable at 0.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-94","question":"The curve x = t² − 1, y = t³ − t passes through the origin twice. The angle between its two tangents at the origin is:","options":["π/2","π/3","π/4","π/6"],"answer":0,"explanation":"x = y = 0 gives t = ±1. dy/dx = (3t² − 1)/(2t) equals 1 at t = 1 and −1 at t = −1. Slopes 1 and −1 have product −1, so the tangents are perpendicular: the angle is π/2.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-differentiation-applications-95","question":"The minimum value of 2^(sin x) + 2^(cos x) over real x is:","options":["2^(1 + 1/√2)","2^(1 − 1/√2)","2^(−1/√2)","1"],"answer":1,"explanation":"By AM–GM, 2^(sin x) + 2^(cos x) ≥ 2√(2^(sin x + cos x)) = 2^(1 + (sin x + cos x)/2) ≥ 2^(1 − √2/2), since sin x + cos x ≥ −√2. Both equalities hold at x = 5π/4 (sin x = cos x = −1/√2), so the minimum is 2^(1 − 1/√2) ≈ 1.22.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-differentiation-applications-96","question":"For −1 < x < 1, d/dx (sin⁻¹x + cos⁻¹x) equals:","options":["0","1","2/√(1 − x²)","π/2"],"answer":0,"explanation":"sin⁻¹x + cos⁻¹x = π/2 is a constant, so its derivative is 0. (The individual derivatives ±1/√(1 − x²) cancel.)","difficulty":"easy","source":"JEE Main"},
  {"id":"math-differentiation-applications-97","question":"The slope of the normal to the curve y = ln x at the point where x = 2 is:","options":["1/2","2","−1/2","−2"],"answer":3,"explanation":"The tangent slope is dy/dx = 1/x = 1/2 at x = 2. The normal slope is the negative reciprocal, −2.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-differentiation-applications-98","question":"If y = xˣ (x > 0), then dy/dx at x = e equals:","options":["eᵉ","2eᵉ","e^(e + 1)","2e"],"answer":1,"explanation":"ln y = x ln x, so y′/y = ln x + 1 and y′ = xˣ(1 + ln x). At x = e: eᵉ(1 + 1) = 2eᵉ.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-differentiation-applications-99","question":"The volume of a sphere increases at 8π cm³/s. When the radius is 2 cm, the radius increases at:","options":["1 cm/s","1/2 cm/s","2 cm/s","1/4 cm/s"],"answer":1,"explanation":"V = (4/3)πr³ gives dV/dt = 4πr² dr/dt. So 8π = 4π(4) dr/dt and dr/dt = 1/2 cm/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-differentiation-applications-100","question":"If x = a cos t and y = a sin t (a > 0), then d²y/dx² at t = π/4 equals:","options":["2√2/a","−√2/a","−1/a","−2√2/a"],"answer":3,"explanation":"dy/dx = (a cos t)/(−a sin t) = −cot t. Then d²y/dx² = (d/dt(−cot t))/(dx/dt) = cosec²t/(−a sin t) = −1/(a sin³t). At t = π/4, sin³t = 1/(2√2), giving −2√2/a.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-differentiation-applications-101","question":"On its domain x > −1, the function f(x) = x − ln(1 + x) is strictly increasing on:","options":["(0, ∞)","(−1, 0)","(−1, ∞)","(1, ∞)"],"answer":0,"explanation":"f′(x) = 1 − 1/(1 + x) = x/(1 + x). For x > −1 the denominator is positive, so f′ > 0 exactly when x > 0. (f decreases on (−1, 0) and has its minimum 0 at x = 0.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-differentiation-applications-102","question":"The maximum value of f(x) = x(1 − x)² on [0, 1] is:","options":["1/4","1/27","4/27","8/27"],"answer":2,"explanation":"f′(x) = (1 − x)² − 2x(1 − x) = (1 − x)(1 − 3x). The interior critical point is x = 1/3, where f = (1/3)(4/9) = 4/27; the end values are 0.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-differentiation-applications-103","question":"The value of c given by Lagrange's mean value theorem for f(x) = eˣ on [0, 1] is:","options":["1/2","e − 1","1/(e − 1)","ln(e − 1)"],"answer":3,"explanation":"We need f′(c) = (f(1) − f(0))/(1 − 0) = e − 1, i.e. eᶜ = e − 1, so c = ln(e − 1) ≈ 0.541, which lies in (0, 1).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-104","question":"The acute angle between the curves y = 2ˣ and y = 3ˣ at their common point is:","options":["tan⁻¹(ln(3/2))","π/4","tan⁻¹[(ln 3 − ln 2)/(1 + ln 2 · ln 3)]","tan⁻¹[(ln 3 + ln 2)/(1 − ln 2 · ln 3)]"],"answer":2,"explanation":"They meet only at (0, 1), where the slopes are ln 2 and ln 3. The angle θ between lines with slopes m₁, m₂ has tan θ = |m₁ − m₂|/(1 + m₁m₂) = (ln 3 − ln 2)/(1 + ln 2 · ln 3).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-105","question":"The maximum value of f(x) = (x + 1)/(x² + 3) over real x is:","options":["1/3","1/2","1","2/3"],"answer":1,"explanation":"f′(x) = [(x² + 3) − 2x(x + 1)]/(x² + 3)² = (3 − 2x − x²)/(x² + 3)², which vanishes at x = 1 and x = −3. f(1) = 2/4 = 1/2 is the maximum (f(−3) = −1/6 is the minimum, and f → 0 at ±∞).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-106","question":"The shortest distance from the point (3, 0) to the parabola y² = 4x is:","options":["2√2","3","2","√5"],"answer":0,"explanation":"For the point (t², 2t), the squared distance is (t² − 3)² + 4t² = t⁴ − 2t² + 9 = (t² − 1)² + 8. It is least at t² = 1, i.e. at (1, ±2), giving distance √8 = 2√2 (smaller than the distance 3 to the vertex).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-107","question":"The tangent at any point of the curve xy = 4 forms a triangle with the coordinate axes. Its area is:","options":["8 for every point","4 for every point","16 for every point","different for different points"],"answer":0,"explanation":"At (t, 4/t) the slope is −4/t², and the tangent x/(2t) + y/(8/t) = 1 has intercepts 2t and 8/t. The area is (1/2)(2t)(8/t) = 8, independent of t.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-108","question":"For f(x) = x³ − 3x on [−2, 2], the values of c given by Lagrange's mean value theorem are:","options":["0 only","±2/√3","±1","±√3/2"],"answer":1,"explanation":"The chord slope is [f(2) − f(−2)]/4 = (2 − (−2))/4 = 1. So 3c² − 3 = 1, c² = 4/3, c = ±2/√3 ≈ ±1.155, both inside (−2, 2).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-109","question":"The largest area of a rectangle inscribed in a semicircle of radius r, with one side along the diameter, is:","options":["r²/2","2r²","r²","πr²/4"],"answer":2,"explanation":"With the vertex at angle θ, the rectangle has width 2r cos θ and height r sin θ, so area = r² sin 2θ. Its maximum is r², at θ = π/4.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-110","question":"The function f(x) = x/ln x is strictly decreasing on:","options":["(0, e)","(e, ∞)","(1, e) only","each of (0, 1) and (1, e)"],"answer":3,"explanation":"f′(x) = (ln x − 1)/(ln x)², defined for x > 0, x ≠ 1. It is negative exactly when ln x < 1, i.e. on (0, 1) and on (1, e) separately; f is not monotonic on (0, e) as a whole because of the infinite jump at x = 1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-111","question":"The function f(x) = ax + sin x is increasing on the whole real line exactly when:","options":["a > 1","a ≥ −1","a ≥ 1","a > 0"],"answer":2,"explanation":"f′(x) = a + cos x ≥ 0 for all x needs a ≥ 1 (cos x can be −1). For a = 1, f′ = 1 + cos x vanishes only at isolated points, so f is still (strictly) increasing.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-112","question":"For the curve x = t + 1/t, y = t − 1/t, the value of d²y/dx² at t = 2 is:","options":["−32/27","32/27","−4/27","8/27"],"answer":0,"explanation":"x² − y² = 4, so x = y y′ and then 1 = y′² + y y″, giving y″ = (1 − y′²)/y = (y² − x²)/y³ = −4/y³. At t = 2, y = 3/2, so y″ = −4/(27/8) = −32/27.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-113","question":"For f(x) = 1/(x² − 1), the fourth derivative f⁽⁴⁾(0) equals:","options":["24","0","−12","−24"],"answer":3,"explanation":"Near 0, 1/(x² − 1) = −(1 + x² + x⁴ + …). The coefficient of x⁴ is −1, and f⁽⁴⁾(0) = 4! × (−1) = −24.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-114","question":"The number of points of local extremum of f(x) = x⁴ − 8x³ + 22x² − 24x is:","options":["2","3","1","4"],"answer":1,"explanation":"f′(x) = 4x³ − 24x² + 44x − 24 = 4(x − 1)(x − 2)(x − 3). The derivative changes sign at each simple root, giving minima at 1 and 3 and a maximum at 2: three extrema.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-differentiation-applications-115","question":"Every tangent to the curve x^(2/3) + y^(2/3) = 4 meets the coordinate axes at two points. The distance between these two points is:","options":["4","8","2","different for different tangents"],"answer":1,"explanation":"Parametrise as x = 8cos³θ, y = 8sin³θ. The tangent is x/(8 cos θ) + y/(8 sin θ) = 1, with intercepts 8 cos θ and 8 sin θ. The segment between them has length √(64cos²θ + 64sin²θ) = 8 for every tangent.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-116","question":"The number of real solutions of eˣ = 1 + x + x²/2 is:","options":["2","3","0","1"],"answer":3,"explanation":"Let g(x) = eˣ − 1 − x − x²/2. Then g′(x) = eˣ − 1 − x ≥ 0 for all x, with equality only at 0, so g is strictly increasing and has at most one zero; g(0) = 0. Exactly one solution.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-117","question":"The least positive a for which x² + a/x ≥ 3 for every x > 0 is:","options":["2","1","4","3/2"],"answer":0,"explanation":"Split a/x into two halves: by AM–GM, x² + a/(2x) + a/(2x) ≥ 3(a²/4)^(1/3), with equality attainable. We need 3(a²/4)^(1/3) ≥ 3, i.e. a² ≥ 4, so the least a is 2 (the minimum of x² + 2/x is 3, at x = 1).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-118","question":"The maximum value of f(x) = sin x · sin 2x on [0, π] is:","options":["1","2/3","4√3/9","√3/2"],"answer":2,"explanation":"f = 2 sin²x cos x = 2(1 − c²)c with c = cos x. d/dc[2c − 2c³] = 2 − 6c² = 0 gives c = 1/√3, so f = 2(2/3)(1/√3) = 4/(3√3) = 4√3/9 ≈ 0.77.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-119","question":"The tangent to y = x³ at a point P (other than the origin) meets the curve again at Q. The slope of the curve at Q is k times the slope at P, where k equals:","options":["2","−2","8","4"],"answer":3,"explanation":"The tangent at P(t, t³) is y = 3t²x − 2t³, and x³ − 3t²x + 2t³ = (x − t)²(x + 2t), so Q has x = −2t. Slopes: 3t² at P and 3(4t²) = 12t² at Q, so k = 4.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-120","question":"A right circular cylinder is inscribed in a right circular cone (sharing its axis). The ratio of the greatest possible volume of the cylinder to the volume of the cone is:","options":["1/2","2/3","4/9","8/27"],"answer":2,"explanation":"For a cone of radius R and height H, a cylinder of radius r has height H(1 − r/R), so V = πr²H(1 − r/R). dV/dr = 0 gives r = 2R/3, V = (4/27)πR²H. Dividing by (1/3)πR²H gives 4/9.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-121","question":"The curve y = |x² − 1| has two one-sided tangents at the point (1, 0). The acute angle between them is:","options":["π/4","tan⁻¹(4/3)","tan⁻¹(3/4)","π/2"],"answer":1,"explanation":"To the left of 1, y = 1 − x² with slope −2; to the right, y = x² − 1 with slope 2. tan θ = |2 − (−2)|/|1 + (2)(−2)| = 4/3, so the acute angle is tan⁻¹(4/3).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-122","question":"The local maximum value of f(x) = (ln x)²/x, x > 0, is:","options":["4/e²","1/e","0","2/e"],"answer":0,"explanation":"f′(x) = ln x (2 − ln x)/x². It changes from − to + at x = 1 (local minimum 0) and from + to − at ln x = 2, i.e. x = e², where f = 4/e².","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-123","question":"The least value of (sin x)/x on the interval (0, π/2] is:","options":["2/π","0","1/2","π/4"],"answer":0,"explanation":"g(x) = sin x/x has g′(x) = cos x (x − tan x)/x² < 0 on (0, π/2), since tan x > x. So g decreases, and its least value is at x = π/2: 1/(π/2) = 2/π (Jordan's inequality sin x ≥ 2x/π).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-124","question":"For f(x) = x⁷, the value of f(1) + f′(1)/1! + f″(1)/2! + … + f⁽⁷⁾(1)/7! is:","options":["2⁷ − 1","2⁷","7!","7 × 2⁶"],"answer":1,"explanation":"By Taylor's theorem about x = 1 (exact for a polynomial), f(1 + h) = Σ f⁽ᵏ⁾(1)hᵏ/k!. Putting h = 1 gives the sum as f(2) = 2⁷ = 128. Equivalently, f⁽ᵏ⁾(1)/k! = ⁷Cₖ, and Σ ⁷Cₖ = 2⁷.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-125","question":"The minimum value of f(x) = |x − 1| + |x − 2| + |x − 3| + … + |x − 10| over real x is:","options":["30","20","25","45"],"answer":2,"explanation":"f is piecewise linear and its slope is (number of k below x) − (number above x). The slope is 0 on [5, 6], the median interval, where f = (4.5 + 3.5 + 2.5 + 1.5 + 0.5) × 2 = 25.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-126","question":"A straight line passes through the point (1, 27) and meets the positive x- and y-axes. The least possible length of the segment between the axes is:","options":["28","√730","30","10√10"],"answer":3,"explanation":"If the line makes angle θ with the x-axis, the segment length is L = 1/cos θ + 27/sin θ. L′ = 0 gives tan³θ = 27, tan θ = 3, so cos θ = 1/√10, sin θ = 3/√10 and L = √10 + 9√10 = 10√10. (In general the minimum is (a^(2/3) + b^(2/3))^(3/2).)","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-127","question":"Which of the following is true?","options":["e^π < π^e","e^π = π^e","e^π > π^e","The comparison cannot be decided without a calculator"],"answer":2,"explanation":"g(x) = ln x/x has g′(x) = (1 − ln x)/x² < 0 for x > e, so g(π) < g(e): ln π/π < 1/e. Multiplying by eπ gives e ln π < π, i.e. π^e < e^π.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-128","question":"The number of points of inflection of the curve y = e^(−x²) is:","options":["2","1","0","4"],"answer":0,"explanation":"y′ = −2x e^(−x²) and y″ = (4x² − 2)e^(−x²). y″ changes sign at x = ±1/√2, so there are exactly 2 points of inflection (the bell curve changes concavity on each side of the peak).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-differentiation-applications-129","question":"The number of real roots of x⁷ + x⁵ + x³ + x + 1 = 0 is:","options":["3","7","0","1"],"answer":3,"explanation":"f′(x) = 7x⁶ + 5x⁴ + 3x² + 1 > 0, so f is strictly increasing and has at most one real root. As an odd-degree polynomial it has at least one (f(−1) = −3 < 0 < f(0) = 1). Exactly one.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

export default questions;
